import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Physical discard cards with live Ability existence. Synthetic source fixtures do not promote older cards. */
public final class DiscardAbilityCountTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static final String COUNT="{\"type\":\"DISCARD_COUNT\",\"target\":\"SELF\",\"ability_id\":\"hide-n-sneak\",\"value\":4,\"comparison\":\">=\"}";
    static final String GLOBAL="{\"type\":\"suppress_abilities\",\"target\":\"SELF\",\"scope\":\"FIELD_HAND_DISCARD\",\"source_has_tool\":true,\"source_evolved_only\":true,\"except_ability_id\":\"garbotoxin\"}";
    static EffectDefinition effect(String json){return EffectRegistry.standard().parse(JsonParser.parseString(json).getAsJsonObject());}
    static AbilityDefinition passive(String id,String json){return new AbilityDefinition(id,"同名测试特性",new AbilityEffect(AbilityEffect.Opcode.COMPOSED,0),EffectSupport.SUPPORTED,null,AbilityDefinition.Kind.PASSIVE,new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(effect(json))))));}
    static AbilityDefinition hide(){return passive("hide-n-sneak","{\"type\":\"passive_effect_guard\",\"target\":\"SELF\",\"source\":\"ABILITY\",\"from\":\"OPPONENT\",\"scope\":\"DAMAGE_AND_EFFECTS\"}");}
    static AttackDefinition attack(){return BundledCombatData.attack(JsonParser.parseString("{\"id\":\"anchor\",\"nameZh\":\"计数测试\",\"energyCost\":{},\"baseDamage\":30,\"damageType\":\"PSYCHIC\",\"effectSupport\":\"SUPPORTED\",\"effects\":[{\"type\":\"conditional\",\"conditions\":["+COUNT+"],\"effects\":[{\"type\":\"damage\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":140}]}]}").getAsJsonObject(),EffectRegistry.standard());}
    static CardDefinition card(String id,CardCategory category,TrainerCategory trainer,boolean basic){return new CardDefinition(id,id,category,trainer,"J",Set.of("international"),basic,id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null);}
    static PokemonProfile profile(String from,List<AbilityDefinition> abilities){return new PokemonProfile(1000,0,from,null,0,null,0,1,List.of(attack(),CopyAttackTest.copier()),abilities,EnergyType.PSYCHIC);}
    static ServerMatch game(){return game(null,null,null);}
    static ServerMatch game(CardDefinition real,PokemonProfile actual,AbilityDefinition actualHide){
        String actor=real==null?"actor":real.id();var definitions=new ArrayList<CardDefinition>();var profiles=new LinkedHashMap<String,PokemonProfile>();
        var draw=new AbilityDefinition("draw","测试抽牌",new AbilityEffect(AbilityEffect.Opcode.DRAW,1),EffectSupport.SUPPORTED,null);
        var hidden=actualHide==null?hide():actualHide;
        profiles.put(actor,actual==null?profile(null,List.of(draw)):actual);profiles.put("base",profile(null,List.of(draw)));
        profiles.put("hide-a",profile(null,List.of(hidden)));profiles.put("hide-b",profile("base",List.of(hidden)));
        profiles.put("decoy",profile(null,List.of(passive("different-id","{\"type\":\"passive_effect_guard\",\"target\":\"SELF\",\"source\":\"ABILITY\",\"from\":\"OPPONENT\",\"scope\":\"DAMAGE_AND_EFFECTS\"}"))));
        profiles.put("global",profile("base",List.of(passive("garbotoxin",GLOBAL))));
        for(var e:profiles.entrySet())definitions.add(real!=null&&e.getKey().equals(actor)?real:card(e.getKey(),CardCategory.POKEMON,TrainerCategory.NONE,e.getValue().evolvesFromDefinitionId()==null));
        var trainers=new LinkedHashMap<String,TrainerProfile>();
        trainers.put("tool",BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"TOOL\",\"effects\":[{\"type\":\"retreat_cost_modifier\",\"target\":\"SELF\",\"amount\":-1}]}").getAsJsonObject(),EffectRegistry.standard()));
        trainers.put("field",new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.PASSIVE_STADIUM,0,0),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(effect("{\"type\":\"suppress_abilities\",\"target\":\"SELF\",\"scope\":\"ALL_IN_PLAY\"}")))))));
        trainers.put("clear",new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.STADIUM_BASIC_RETREAT_REDUCTION,1,0)));
        for(String id:trainers.keySet())definitions.add(card(id,CardCategory.TRAINER,id.equals("tool")?TrainerCategory.TOOL:TrainerCategory.STADIUM,false));definitions.add(card("energy",CardCategory.ENERGY,TrainerCategory.NONE,false));
        var catalog=new CombatCatalog(profiles,Map.of("energy",EnergyType.PSYCHIC),trainers);var decks=new ArrayList<List<CardInstance>>();
        for(UUID player:List.of(A,B)){var list=new ArrayList<CardInstance>();for(int i=0;i<60;i++){String id=i<14?actor:i<22?"base":i<30?"hide-a":i<36?"hide-b":i<40?"decoy":i<44?"global":i<50?"tool":i<53?"field":i<56?"clear":"energy";list.add(new CardInstance(new UUID(player.getLeastSignificantBits(),i+1),player,id));}decks.add(list);}
        for(int seed=0;seed<1000;seed++){
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(definitions),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals(actor))||m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals("base"))))continue;
            for(UUID p:List.of(A,B)){m.chooseOpeningActive(p,hand(m,p,actor).instanceId());m.placeOpeningBench(p,hand(m,p,"base").instanceId());m.startAfterOpening(p);}OpeningTestSupport.complete(m,A,B,0);m.endTurn(A);m.endTurn(B);return m;
        }throw new AssertionError("No discard fixture");
    }
    static CardInstance hand(ServerMatch m,UUID p,String id){return m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).findFirst().orElseThrow();}
    static CardInstance get(ServerMatch m,UUID p,String id){var found=m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(found.isPresent())return found.get();check(m.currentPlayer().equals(p),"Only current owner searches fixture deck");var c=m.privateView(p).deck().stream().filter(v->v.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(p,List.of(c.instanceId()));return c;}
    static void discard(ServerMatch m,String id,int n){for(int i=0;i<n;i++)m.discardHandCardsByEffect(A,A,List.of(get(m,A,id).instanceId()));}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID source(ServerMatch m){UUID id=m.benchPokemonView(A).getFirst().pokemonId();m.evolve(A,id,get(m,A,"global").instanceId());return id;}
    static void tool(ServerMatch m,UUID host){m.playTrainer(A,get(m,A,"tool").instanceId(),host);}
    static int count(ServerMatch m,UUID owner,String ability){try{var method=ServerMatch.class.getDeclaredMethod("discardCount",UUID.class,Map.class);method.setAccessible(true);return (int)method.invoke(m,owner,ability==null?Map.of():Map.of("ability_id",ability));}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    static void attackDamage(ServerMatch m,int expected){m.attack(A,"anchor");check(m.lastAttack().finalDamage()==expected,"Wrong discard threshold damage");}
    public static void main(String[] args){thresholds();liveSuppression();sourceRemoval();opponentAndMultipleSources();relativeCounts();damageMath();copied();schema();System.out.println("DiscardAbilityCountTest passed: physical mixed-print discard counts, precise Ability ID, both players, raw count compatibility, field-only versus cross-zone removal, live source Tool/lock/removal, exempt source, actual copied actor and strict acyclic source schema");}
    static void thresholds(){for(int n:List.of(0,3,4,5)){var m=game();discard(m,"hide-a",Math.min(n,2));discard(m,"hide-b",Math.max(0,n-2));discard(m,"decoy",1);discard(m,"tool",1);check(count(m,A,"hide-n-sneak")==n&&count(m,B,"hide-n-sneak")==0&&count(m,A,null)==n+2,"Count read wrong zone, name or card category");check(count(m,A,"missing")==0,"Missing Ability counted");attackDamage(m,n>=4?170:30);}}
    static void liveSuppression(){var m=game();discard(m,"hide-a",2);discard(m,"hide-b",2);UUID source=source(m);check(count(m,A,"hide-n-sneak")==4,"Toolless source removed discard Abilities");tool(m,source);check(count(m,A,"hide-n-sneak")==0&&m.abilityOptions(A).isEmpty()&&m.abilityOptions(B).isEmpty(),"Cross-zone source ignored field/discard");discard(m,"global",1);check(count(m,A,"garbotoxin")==1,"Exempt Ability removed");m.disableToolEffectsByEffect(A,A,source);check(count(m,A,"hide-n-sneak")==0,"Tool effect suppression removed physical attachment condition");m.playTrainer(A,get(m,A,"field").instanceId(),null);check(count(m,A,"hide-n-sneak")==4&&m.abilityOptions(A).isEmpty(),"Field-only suppression affected discarded Abilities or failed to remove global source");m.endTurn(A);m.playTrainer(B,get(m,B,"clear").instanceId(),null);m.endTurn(B);check(count(m,A,"hide-n-sneak")==0,"Global source did not resume after field lock removed");m.disableAbilityEffectsByEffect(A,A,source);check(count(m,A,"hide-n-sneak")==4,"Temporary source Ability lock ignored");attackDamage(m,170);}
    static void sourceRemoval(){for(boolean leave:List.of(false,true)){var m=game();discard(m,"hide-a",4);UUID s=source(m);tool(m,s);check(count(m,A,"hide-n-sneak")==0,"Source not enabled");if(leave){var p=new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(effect("{\"type\":\"return_to_hand\",\"target\":\"SELF\"}")))));m.executeEffectProgramByRule(A,s,p,EffectTrigger.ON_CARD_PLAYED);}else m.discardToolByEffect(A,A,s,m.benchPokemonView(A).getFirst().attachedTools().getFirst().instanceId());check(count(m,A,"hide-n-sneak")==4,"Source departure/Tool removal left stale lock");attackDamage(m,170);}}
    static void copied(){var m=game();discard(m,"hide-a",4);m.attachEnergy(A,get(m,A,"energy").instanceId(),active(m,A));var o=m.copyAttackOptions(A,"copy").stream().filter(v->v.attackId().equals("anchor")).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",o.pokemonId(),o.entrySequence(),o.attackId(),List.of(),List.of());check(m.lastAttack().finalDamage()==170&&count(m,B,"hide-n-sneak")==0,"Copied attack counted provider discard");}
    static void opponentAndMultipleSources(){var m=game();discard(m,"hide-a",4);UUID own=source(m);tool(m,own);m.endTurn(A);UUID opposing=m.benchPokemonView(B).getFirst().pokemonId();m.evolve(B,opposing,get(m,B,"global").instanceId());m.playTrainer(B,get(m,B,"tool").instanceId(),opposing);m.endTurn(B);m.discardToolByEffect(A,A,own,m.benchPokemonView(A).getFirst().attachedTools().getFirst().instanceId());check(count(m,A,"hide-n-sneak")==0,"Removing one source ignored opposing source");m.discardToolByEffect(A,B,opposing,m.benchPokemonView(B).getFirst().attachedTools().getFirst().instanceId());check(count(m,A,"hide-n-sneak")==4,"Removing last source did not restore discard Abilities");attackDamage(m,170);}
    static void relativeCounts(){var m=game();discard(m,"hide-a",2);m.endTurn(A);for(int i=0;i<3;i++)m.discardHandCardsByEffect(B,B,List.of(get(m,B,"hide-a").instanceId()));m.endTurn(B);for(String mode:List.of("OPPONENT","TARGET","SELF")){var args=new LinkedHashMap<String,String>();args.put("ability_id","hide-n-sneak");args.put("target",mode.equals("SELF")?"OPPONENT_ACTIVE":"SELF");args.put("comparison",mode.equals("SELF")?">=":"<");if(mode.equals("OPPONENT"))args.put("compare_to","OPPONENT");else if(mode.equals("TARGET"))args.put("compare_target","OPPONENT_ACTIVE");else args.put("value","3");var condition=new ConditionDefinition(ConditionType.DISCARD_COUNT,args,List.of());var draw=new EffectDefinition("draw",EffectTarget.SELF,Map.of("amount","1"),List.of(condition),List.of());var program=new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(draw))));int before=m.privateView(A).hand().size();m.executeEffectProgramByRule(A,active(m,A),program,EffectTrigger.ON_CARD_PLAYED);check(m.privateView(A).hand().size()==before+1,"Filtered relative count used raw/wrong discard "+mode);}}
    static void damageMath(){for(String mode:List.of("WEAK","RESIST","PREVENT")){var p=new PokemonProfile(1000,0,null,mode.equals("WEAK")?EnergyType.PSYCHIC:null,mode.equals("WEAK")?2:0,mode.equals("RESIST")?EnergyType.PSYCHIC:null,mode.equals("RESIST")?30:0,1,List.of(attack()),List.of(),EnergyType.PSYCHIC);var m=game(null,p,null);discard(m,"hide-a",4);if(mode.equals("PREVENT")){var shield=effect(EffectOriginProtectionTest.shield("ATTACK","DAMAGE_ONLY","OPPONENT_ACTIVE","LEAVES_PLAY"));m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(shield)))),EffectTrigger.ON_CARD_PLAYED);}attackDamage(m,mode.equals("WEAK")?340:mode.equals("RESIST")?140:0);}}
    static void schema(){AttackProgramRules.validate(attack());for(String bad:List.of(GLOBAL.replace("true","false"),GLOBAL.replace("SELF","OPPONENT_ACTIVE"),GLOBAL.replace("garbotoxin","Bad ID")))reject(()->effect(bad));reject(()->passive("wrong",GLOBAL));reject(()->new CombatCatalog(Map.of("bad",profile(null,List.of(passive("garbotoxin",GLOBAL)))),Map.of()));reject(()->new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.PASSIVE_STADIUM,0,0),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(effect(GLOBAL)))))));for(var args:List.of(Map.of("ability_id","Bad ID","value","4"),Map.of("ability_id","hide-n-sneak","value","4","target","ALL_OWN_POKEMON"),Map.of("ability_id","hide-n-sneak","value","4","unexpected","true")))reject(()->NumericConditionPolicy.validate(new ConditionDefinition(ConditionType.DISCARD_COUNT,args,List.of())));reject(()->AbilitySuppressionProgram.validateDependency(new ConditionDefinition(ConditionType.DISCARD_COUNT,Map.of("ability_id","hide-n-sneak","value","4"),List.of())));}
}
